{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Tolfenamic acid, a direct anthranilic acid analogue with a secondary amine and carboxylic acid, had an absolute oral bioavailability of 63.2% in healthy volunteers after oral dosing vs IV, supporting high F for the query's similar anthranilic acid core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Diclofenac, another carboxylic acid-containing secondary-amine drug, had a mean absolute bioavailability of 65.1% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Telmisartan, a carboxylic acid-containing drug, showed absolute bioavailability of 57.4% in humans, indicating that acidic drugs with this transfer profile can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Safinamide, a small polar molecule with amine and amide functionalities, had an absolute bioavailability of 95% in humans, demonstrating that high F is common among the highly transferable evidence set.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rigosertib, a larger polar sulfonate-containing carboxylic acid, had a mean absolute oral bioavailability of only 13.9% in fed MDS patients, providing affirmative low-F evidence; however, its larger size and fed-state conditions reduce its weight relative to the closer anthranilic acid analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is furosemide, an anthranilic acid diuretic with a carboxylic acid, sulfonamide, and furfurylamine. Direct absolute bioavailability measurements in close anthranilic acid analogues (tolfenamic acid 63%, diclofenac 65%) and other carboxylic acid drugs (telmisartan 57%) consistently exceed 20%, supporting high F. The one affirmative low-F analogue (rigosertib, fed 13.9%) is structurally larger and measured under fed conditions, so it does not overturn the consistent moderate-to-high F pattern. Prediction: high.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for the query molecule itself in the provided evidence.",
    "Furosemide bioavailability can be variable with formulation, prandial state, and disease; no query-specific formulation data are available.",
    "The low-F evidence (rigosertib fed) comes from a different chemical class and fed state, limiting direct extrapolation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

